import { useCallback, useEffect, useRef, useState } from 'react'
import {
  CLOSE_NOT_FOUND,
  chatSocketUrl,
  endConversation,
  getConversation,
  type Message,
  type ServerEvent,
} from './api'

export type ChatStatus = 'connecting' | 'open' | 'closed'

const MAX_RETRY_DELAY_MS = 10_000

/**
 * Owns one conversation: loads its history, keeps a WebSocket open, and streams the agent's reply
 * into `streaming` until the server confirms it with `message_done`.
 *
 * On a dropped connection it reconnects and reloads history, so a reply lost mid-stream is
 * regenerated by the server rather than leaving the chat stuck.
 */
export function useChat(conversationId: string) {
  const [scenario, setScenario] = useState('')
  const [messages, setMessages] = useState<Message[]>([])
  const [streaming, setStreaming] = useState('')
  const [status, setStatus] = useState<ChatStatus>('connecting')
  const [error, setError] = useState<string | null>(null)
  const [ended, setEnded] = useState(false)
  const socketRef = useRef<WebSocket | null>(null)
  const localId = useRef(0)
  const endedRef = useRef(false)

  useEffect(() => {
    let cancelled = false
    let retries = 0
    let timer: ReturnType<typeof setTimeout> | undefined

    const scheduleRetry = () => {
      const delay = Math.min(1000 * 2 ** retries, MAX_RETRY_DELAY_MS)
      retries += 1
      timer = setTimeout(connect, delay)
    }

    async function connect() {
      setStatus('connecting')
      try {
        const detail = await getConversation(conversationId)
        if (cancelled) return
        setScenario(detail.scenario)
        setMessages(detail.messages)
        setStreaming('')
        if (detail.ended_at) {
          // Read-only: no socket, so the server never sends an opener or accepts messages.
          endedRef.current = true
          setEnded(true)
          setStatus('closed')
          return
        }
      } catch {
        if (cancelled) return
        setStatus('closed')
        setError('Could not load the conversation.')
        scheduleRetry()
        return
      }

      const socket = new WebSocket(chatSocketUrl(conversationId))
      socketRef.current = socket
      socket.onopen = () => {
        retries = 0
        setStatus('open')
        setError(null)
      }
      socket.onmessage = (event: MessageEvent<string>) => {
        const data = JSON.parse(event.data) as ServerEvent
        if (data.type === 'user_message_saved') {
          // Swap the oldest optimistic id for the real one so later events can find the message.
          setMessages((prev) => {
            const index = prev.findIndex((m) => m.id.startsWith('local-'))
            if (index < 0) return prev
            return prev.map((m, i) => (i === index ? { ...m, id: data.id } : m))
          })
        } else if (data.type === 'corrections') {
          setMessages((prev) =>
            prev.map((m) => (m.id === data.message_id ? { ...m, corrections: data.corrections } : m)),
          )
        } else if (data.type === 'token') {
          setStreaming((s) => s + data.text)
        } else if (data.type === 'message_done') {
          setStreaming('')
          setMessages((prev) => [
            ...prev,
            {
              id: data.id,
              role: 'assistant',
              content: data.content,
              created_at: new Date().toISOString(),
            },
          ])
        } else {
          setStreaming('')
          setError(data.detail)
        }
      }
      socket.onclose = (event: CloseEvent) => {
        if (cancelled || endedRef.current) return
        socketRef.current = null
        setStatus('closed')
        if (event.code === CLOSE_NOT_FOUND) {
          setError('Conversation not found.')
          return
        }
        scheduleRetry()
      }
    }

    void connect()

    return () => {
      cancelled = true
      clearTimeout(timer)
      socketRef.current?.close()
      socketRef.current = null
    }
  }, [conversationId])

  const send = useCallback((content: string): boolean => {
    const socket = socketRef.current
    const text = content.trim()
    if (!text || socket?.readyState !== WebSocket.OPEN) return false
    localId.current += 1
    setError(null)
    setMessages((prev) => [
      ...prev,
      {
        id: `local-${localId.current}`,
        role: 'user',
        content: text,
        created_at: new Date().toISOString(),
      },
    ])
    socket.send(JSON.stringify({ type: 'message', content: text }))
    return true
  }, [])

  /** End the conversation for good. Resolves true once the server confirms. */
  const end = useCallback(async (): Promise<boolean> => {
    try {
      await endConversation(conversationId)
    } catch {
      setError('Could not end the conversation.')
      return false
    }
    endedRef.current = true
    setEnded(true)
    socketRef.current?.close()
    return true
  }, [conversationId])

  const last = messages[messages.length - 1]
  const waitingForReply =
    !ended &&
    status === 'open' && !error && streaming === '' && (!last || last.role === 'user')

  return { scenario, messages, streaming, status, error, waitingForReply, ended, send, end }
}
